INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass der Vergleichsoperator = immer auf Gleichheit prüft?', 2, '[{"text": "Ja", "correct": true, "because": "Testet Wertegleichheit"}, {"text": "Nein", "correct": false, "because": "= ist für Zuweisung in manchen Sprachen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator prüft, ob ein Wert kleiner als ein anderer ist?', 3, '[{"text": "<", "correct": true, "because": "Vergleicht numerische Werte"}, {"text": "<=", "correct": false, "because": "Einschließlich Gleichheit"}, {"text": "!=", "correct": false, "because": "Prüft Ungleichheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren werden in SQL-Abfragen für Vergleiche genutzt?', 5, '[{"text": "=", "correct": true, "because": "Prüft Gleichheit"}, {"text": ">", "correct": true, "because": "Prüft größer"}, {"text": "&&", "correct": false, "because": "Logischer Operator"}, {"text": "+", "correct": false, "because": "Arithmetischer Operator"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) != prüft Ungleichheit. b) Es ist dasselbe wie <>.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Beide prüfen Ungleichheit in SQL"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Verwendung von Vergleichsoperatoren in einer Abfrage?', 4, '[{"text": "Datentypen", "correct": false, "because": "Müssen kompatibel sein"}, {"text": "Operatorreihenfolge", "correct": false, "because": "Beeinflusst Ergebnisse"}, {"text": "Schriftart", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob >= auch Gleichheit prüft?', 2, '[{"text": "Ja", "correct": true, "because": "Einschließlich Gleichheit"}, {"text": "Nein", "correct": false, "because": "Umfasst ="}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Operator ist in SQL für „nicht gleich“ geeignet?', 3, '[{"text": "<>", "correct": true, "because": "Standard für Ungleichheit"}, {"text": "==", "correct": false, "because": "Nicht in SQL"}, {"text": "<", "correct": false, "because": "Nur kleiner"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass = in allen Sprachen dasselbe bedeutet. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "In manchen Sprachen Zuweisung"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist <= dasselbe wie < oder =?', 2, '[{"text": "Ja", "correct": true, "because": "Kombiniert beide Bedingungen"}, {"text": "Nein", "correct": false, "because": "Einschließt Gleichheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren sind für numerische Vergleiche in einer Datenbank geeignet?', 4, '[{"text": ">", "correct": true, "because": "Prüft größer"}, {"text": "<=", "correct": true, "because": "Prüft kleiner oder gleich"}, {"text": "||", "correct": false, "because": "Logische Verknüpfung"}, {"text": "%", "correct": false, "because": "Arithmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Verwendung von Vergleichsoperatoren in einer Abfrage?', 4, '[{"text": "Korrekte Datentypen", "correct": true, "because": "Sichert genaue Ergebnisse"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Sekundär"}, {"text": "Operatorlänge", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) > prüft, ob ein Wert größer ist. b) Es prüft auch Gleichheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, > schließt = aus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Vergleichsoperatoren effektiv zu nutzen?', 3, '[{"text": "Kompatible Datentypen", "correct": false, "because": "Vermeidet Fehler"}, {"text": "Klar definierte Werte", "correct": false, "because": "Sichert Präzision"}, {"text": "Farbcodierung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich in SQL prüfe, ob ein Wert ungleich ist?', 4, '[{"text": "Mit != oder <>", "correct": true, "because": "Beide prüfen Ungleichheit"}, {"text": "Mit =!", "correct": false, "because": "Kein gültiger Operator"}, {"text": "Mit <=", "correct": false, "because": "Prüft kleiner oder gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Vergleichsoperatoren nur für Zahlen funktionieren. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Strings, Daten"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten hat der Operator = bei NULL-Werten in SQL?', 3, '[{"text": "Ergibt NULL", "correct": true, "because": "NULL-Vergleiche sind speziell"}, {"text": "Prüft Gleichheit", "correct": false, "because": "Nicht direkt mit ="}, {"text": "Wirft Fehler", "correct": false, "because": "Kein Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Prüft != dasselbe wie <>?', 2, '[{"text": "Ja", "correct": true, "because": "Beide für Ungleichheit"}, {"text": "Nein", "correct": false, "because": "Funktion identisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operatoren sind für String-Vergleiche in SQL geeignet?', 4, '[{"text": "=", "correct": true, "because": "Prüft String-Gleichheit"}, {"text": "!=", "correct": true, "because": "Prüft Ungleichheit"}, {"text": "*", "correct": false, "because": "Arithmetisch"}, {"text": "++", "correct": false, "because": "Kein SQL-Operator"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwendung von Vergleichsoperatoren unwichtig?', 3, '[{"text": "Datentyp-Kompatibilität", "correct": false, "because": "Sichert Korrektheit"}, {"text": "Abfrageoptimierung", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Syntaxhervorhebung", "correct": true, "because": "Nur visuelle Hilfe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich in SQL prüfen will, ob ein Wert größer oder gleich ist?', 4, '[{"text": "Operator >= verwenden", "correct": true, "because": "Prüft beide Bedingungen"}, {"text": "Operator > allein", "correct": false, "because": "Schließt Gleichheit aus"}, {"text": "Operator = nutzen", "correct": false, "because": "Nur Gleichheit"}]');
